Given a queue q of even size. Rearrange the elements by interleaving the first half with the second half.Note: Interleaving means take one element from the first half, then one element from the second half, then the next element from the first half, then the next element from the second half, and continue this process until the queue is fully rearranged.Examples:Input: q = [2, 4, 3, 1]Output: [2, 3, 4, 1]Explanation: We place the first element of the first half 2 and after that place the first element of second half 3 and after that repeat the same process one more time so the resulting queue will be [2, 3, 4, 1]Input: q = [3, 5]Output: [3, 5]Explanation: We place the first element of the first half 3 and first element of the second half 5 so the resulting queue is [3, 5]Try It YourselfTable of ContentUsing Queue - O(n) Time and O(n) SpaceGetting Result in an Array - O(n) Time and O(n) SpaceUsing Stack - O(n) Time and O(n/2) SpaceUsing Queue - O(n) Time and O(n) SpaceThe idea is to split the queue into two equal halves while maintaining their order, and then merge them by alternately taking elements from each half and inserting them back into the original queue to form the interleaved sequence.Move first half elements into firstHalf queue.  Move remaining elements into secondHalf queue.  Alternately dequeue from both and enqueue back into original queue.  Repeat until both halves are empty. Note: In JavaScript, there is no built-in queue data structure, so we create a custom queue class.
            C++

    #include <iostream>
#include <queue>
#include<algorithm>
using namespace std;

void rearrangeQueue(queue<int>& q) {
    int n = q.size();
    queue<int> firstHalf, secondHalf;

    // Split the queue into two halves
    for (int i = 0; i < n / 2; i++) {  
        firstHalf.push(q.front());
        q.pop();
    }

    // Move the remaining elements to the second half
    while (!q.empty()) {
        secondHalf.push(q.front());
        q.pop();
    }

    // Interleave the elements from both halves
    while (!firstHalf.empty() && !secondHalf.empty()) {
        q.push(firstHalf.front());
        firstHalf.pop();
        q.push(secondHalf.front());
        secondHalf.pop();
    }
}

int main() {
    queue<int> q;
    q.push(2);
    q.push(4);
    q.push(3);
    q.push(1);

    rearrangeQueue(q);

    while (!q.empty()) {
        cout << q.front() << " ";
        q.pop();
    }

    return 0;
}


